              "slug": "arcane-edge",
              "sourcePath": "content/classes/spellblade/talents/tier-1/arcane-edge/index.md",
              "sourceFolder": "content/classes/spellblade/talents/tier-1/arcane-edge",
              "tier": "Tier 1",
              "ranks": 5,
              "prerequisite": "None",
