              "tier": "Tier 3",
              "ranks": 5,
              "prerequisite": "None",
              "cost": "9 TP",
              "cooldown": "None",
              "abilityType": "Activated",
              "manaCost": "N/A",
              "staminaCost": "30 SP",
              "hpCost": "N/A",
