              "tier": "Tier 5",
              "ranks": 5,
              "prerequisite": "None",
              "cost": "15 TP",
              "cooldown": "1 Use per Long Rest",
              "abilityType": "Activated",
              "manaCost": "250 MP",
              "staminaCost": "N/A",
              "hpCost": "N/A",
