              "tier": "Tier 4",
              "ranks": 5,
              "prerequisite": "None",
              "cost": "6 TP",
              "cooldown": "Long Rest",
              "abilityType": "Active (Divine Miracle)",
              "manaCost": "Variable",
              "staminaCost": "Variable",
